const uniq = list => [...new Set(list)];
const in3 = list => uniq(list.filter(s => SCHOOL[3].includes(s)).concat(list.flatMap(s => NEXT_OF[s] || [])));

// 학년에 맞게 과목을 묶어서 돌려줌: [[제목, 과목들, 점선 표시 여부], ...]
function gradeSubjects(list, g) {
  if (g === 1) {
    const now = uniq(list.flatMap(s => SCHOOL[1].includes(s) ? [s] : (BASE_OF[s] ? [BASE_OF[s]] : [])));
    const later = uniq(list.filter(s => SCHOOL[2].includes(s)));
    return [['지금 배우는 과목 (1학년)', now, false], ['2학년 때 선택해 볼 과목', later, true]];
  }
  if (g === 2) {
    const now = uniq(list.filter(s => SCHOOL[2].includes(s)));
    return [['2학년 관련 과목', now, false], ['3학년 때 이어서 선택해 볼 과목', in3(list), true]];
  }
  const before = uniq(list.filter(s => SCHOOL[2].includes(s)));
  return [['3학년 관련 과목', in3(list), false], ['2학년 때 배운 바탕 과목', before, true]];
}

