pushTopic("elec", {"id":"elec-semirecycle","title":"반도체 제조 공정의 용수 사용과 재이용","kyeol":"cmp","methods":["literature","data"],"grades":[2,3],"link":"반도체·환경 엔지니어는 공정 품질을 유지하면서 물 사용량과 폐수를 줄이는 기술을 연구해요.","questions":["반도체 공정에서 초순수가 필요한 이유는 무엇일까?","기업 지속가능경영보고서의 용수 취수·재이용 지표는 기업별로 어떻게 정의되고 달라질까?","용수 재이용을 늘릴 때 품질·에너지·비용 측면의 상충관계는 무엇일까?"],"research":["반도체 세정 공정과 초순수","용수 취수·사용·재이용 지표","폐수 처리와 에너지 사용","지속가능경영보고서 읽는 법"],"steps":["반도체 기업 2~3곳의 최근 지속가능경영보고서를 정해요.","용수 관련 지표의 정의와 단위를 먼저 맞춰요.","3~5년 수치를 표와 그래프로 정리해요.","재이용률이 높아지는 이유와 공정 투자 사례를 보고서에서 확인해요.","회사 규모·공장 위치가 달라 단순 순위를 매기기 어렵다는 한계를 적어요.","공정 품질과 환경성을 함께 보는 개선 질문을 제안해요."],"subjects":["화학","물질과 에너지","지구시스템과학","기후변화와 환경생태"],"keywords":["반도체 초순수","반도체 용수 재이용","반도체 지속가능경영 물"],"next":["반도체 폐수 자원회수","초순수 제조의 막 기술","반도체 공정 에너지 사용"],"difficulty":3,"time":"8~10시간","tools":"기업 보고서, 스프레드시트","approval":"불필요","output":"용수 지표 비교 대시보드"});
pushTopic("chem", {"id":"chem-upcycle","title":"폐자원을 활용한 친환경 복합소재 만들기","kyeol":"exp","methods":["making","experiment","literature"],"grades":[1,2,3],"link":"신소재 연구원은 버려지는 재료의 성분과 구조를 활용해 새로운 복합소재를 설계하고 성능을 시험해요.","questions":["계란 껍데기처럼 안전하게 구할 수 있는 폐자원의 혼합 비율에 따라 시편의 강도와 흡수율은 어떻게 달라질까?","같은 재료량에서 결합제 비율을 바꾸면 건조 후 특성이 어떻게 달라질까?","성능뿐 아니라 제작 에너지·재사용성까지 고려하면 어떤 조성이 적절할까?"],"research":["탄산칼슘과 충전재의 역할","복합재료와 결합제","흡수율·하중 시험","업사이클링과 전과정 관점"],"steps":["교사와 안전한 재료만 선정하고 균사체 배양처럼 미생물 관리가 필요한 방법은 자율실험에서 제외해요.","세척·건조한 계란 껍데기 등 안전한 재료를 일정한 크기로 준비해요.","결합제 비율을 달리한 작은 시편을 같은 크기로 제작해 충분히 건조해요.","같은 방법으로 질량·물 흡수율·간단한 하중 지지 정도를 반복 측정해요.","성능과 제작 편의·폐기 방법을 함께 비교해요."],"safety":["식품용이 아닌 시편은 먹거나 피부에 오래 접촉하지 않아요.","가열·유기용매·강산·강염기 사용은 하지 않거나 반드시 교사 관리 아래 실시해요."],"subjects":["통합과학1·2","화학","화학 반응의 세계","융합과학 탐구"],"keywords":["계란껍데기 복합소재","업사이클링 신소재","탄산칼슘 복합재"],"next":["천연섬유 보강 효과","포장재 흡수율 비교","폐자원 소재의 전과정 평가"],"difficulty":2,"time":"6~9시간","tools":"안전한 폐자원, 저울, 자, 물","approval":"교사 승인 필요","output":"시편 + 성능 비교표"});
pushTopic("arch", {"id":"arch-smartcity","title":"도시 빗물 관리(LID) 모형의 성능 비교","kyeol":"exp","methods":["making","experiment","data"],"grades":[1,2,3],"link":"도시·토목 분야에서는 물이 스며들고 머무는 시간을 늘려 집중호우 때 유출을 줄이는 저영향개발(LID)을 설계해요.","questions":["불투수 포장·모래·식생 토양 모형은 같은 강우에서 유출량과 유출 시작 시간이 얼마나 다를까?","경사도를 바꾸면 각 표면의 차이가 어떻게 달라질까?","학교에서 LID를 적용한다면 어느 공간이 적절할까?"],"research":["저영향개발(LID)","침투·저류·유출","투수성 포장과 빗물정원","모형 실험의 축척 한계"],"steps":["같은 크기·경사의 상자 3개에 서로 다른 표면 모형을 만들어요.","같은 높이에서 같은 양의 물을 같은 시간 동안 뿌려요.","유출 시작 시간과 모인 물의 부피를 측정해요.","각 조건을 3회 이상 반복해 평균을 구해요.","경사도 한 조건을 추가해 차이가 유지되는지 확인해요.","학교 지도에 적용 후보 공간을 표시하고 근거를 적어요."],"subjects":["통합사회1·2","지구과학","도시의 미래 탐구","융합과학 탐구"],"keywords":["LID 저영향개발","투수성포장 유출량","빗물정원 학교"],"next":["학교 불투수면 지도","침수 위험과 강우량 자료","빗물 저장 탱크 용량 계산"],"difficulty":2,"time":"6~8시간","tools":"모형 상자, 물, 계량컵, 타이머","approval":"교사 승인 권장","output":"유출 비교 그래프 + 학교 적용안"});
pushTopic("biz", {"id":"biz-platform-2","title":"플랫폼 수수료 체계가 판매자와 소비자에게 미치는 영향","kyeol":"soc","methods":["literature","math","survey"],"grades":[2,3],"link":"경제·경영 분야에서는 플랫폼의 정액·정률 수수료가 가격, 판매자 이익, 소비자 선택에 미치는 영향을 분석해요.","questions":["같은 매출에서 정률제와 정액제 수수료는 판매자 이익을 어떻게 다르게 만들까?","주문 금액이 달라질 때 어떤 수수료 구조가 유리한지 손익분기점을 찾을 수 있을까?","소비자는 배달비·쿠폰·최소주문금액을 어떻게 종합해 실제 지출을 판단할까?"],"research":["양면시장과 플랫폼","정액·정률 수수료","고정비·변동비·손익분기점","가격 전가와 소비자 후생"],"steps":["실제 업체를 특정해 비공개 자료를 요구하지 않고 공개된 수수료 사례 또는 가상 시나리오를 사용해요.","주문 금액과 주문 건수를 여러 값으로 바꾸며 판매자 비용을 계산해요.","정액제와 정률제가 같아지는 지점을 계산해요.","교사 승인 후 소비자의 가격 인식은 익명 시나리오 설문으로 보조 조사해요.","수수료만으로 플랫폼 가치를 판단할 수 없다는 한계를 적어요."],"subjects":["경제","금융과 경제생활","대수","실용 통계","사회와 문화"],"keywords":["플랫폼 수수료 정률제 정액제","배달 플랫폼 손익분기점","양면시장"],"next":["공공앱과 민간앱 비교","쿠폰이 실제 지출에 미치는 영향","플랫폼 네트워크 효과"],"difficulty":2,"time":"6~8시간","tools":"공개자료, 스프레드시트, 선택 설문","approval":"설문 시 교사 승인","output":"수수료 시나리오 계산표 + 정책 제안"});
pushTopic("soc", {"id":"soc-ai-copyright","title":"생성형 AI 학습·생성물의 저작권 쟁점 비교","kyeol":"cmp","methods":["literature"],"grades":[2,3],"link":"법률·정책 연구자는 새로운 기술과 기존 권리 사이의 충돌을 법 조문·판례·정책 자료로 비교해요.","questions":["AI 학습을 위한 저작물 이용에서 국가별 법적 기준은 어떻게 다른가?","AI 생성물의 저작자성은 인간의 창작적 기여 정도에 따라 어떻게 판단되고 있을까?","학교 과제·홍보물에서 AI 생성물을 사용할 때 학생이 지켜야 할 출처·권리 원칙은 무엇일까?"],"research":["저작권의 보호 대상과 저작자성","공정 이용과 정보분석 관련 제도","AI 학습 데이터 소송의 쟁점","서비스 약관과 라이선스"],"steps":["법령·정부기관·법원 자료를 우선해 3개 이상의 쟁점을 골라요.","사건별로 당사자 주장·핵심 쟁점·현재 절차 또는 판단을 구분해 적어요.","국가별 제도를 같은 평가 기준으로 비교해요.","진행 중인 소송은 확정 판결처럼 표현하지 않아요.","학생용 AI 생성물 사용 체크리스트를 만들어요."],"subjects":["법과 사회","매체 의사소통","정치","현대사회와 윤리"],"keywords":["생성형 AI 저작권","AI 학습데이터 저작권","AI 생성물 저작자성"],"next":["AI 이미지 라이선스 비교","학교 과제의 AI 출처표시","창작자 보상 방식 비교"],"difficulty":3,"time":"8~12시간","tools":"법령·판례·정책자료","approval":"불필요","output":"쟁점 비교표 + 학생용 권리 체크리스트"});
pushTopic("media", {"id":"media-algorithm-echo","title":"추천 알고리즘과 필터버블을 어떻게 관찰할까?","kyeol":"data","methods":["observe","survey","literature"],"grades":[1,2,3],"link":"미디어 연구자는 추천 시스템을 단순 체험하는 데서 그치지 않고 노출 패턴과 이용자 행동을 기록해 해석해요.","questions":["추천 화면의 상위 콘텐츠를 일정 기준으로 분류하면 주제 다양성은 어느 정도일까?","이용자가 다른 관점을 일부러 찾는 습관과 추천 콘텐츠 신뢰도 사이에 어떤 관계가 있을까?","플랫폼 공식 설명과 실제 관찰에서 확인되는 점·확인할 수 없는 점은 무엇일까?"],"research":["추천 시스템의 기본 원리","필터버블과 반향실 개념","관찰 연구의 재현성 한계","플랫폼 개인정보·이용정책"],"steps":["실제 친구 계정을 조작하거나 새 계정을 대량 생성하지 않아요.","공식 정책 문서에서 추천에 사용된다고 밝힌 신호를 먼저 조사해요.","개인정보가 보이지 않게 자신의 추천 화면 상위 10~20개를 주제별로 분류해요.","가능하면 다른 시점에 같은 기준으로 반복 기록해요.","교사 승인 후 추천 신뢰·다른 관점 탐색 습관을 익명 설문으로 조사할 수 있어요.","관찰 결과만으로 알고리즘 내부 원리를 단정하지 않아요."],"subjects":["정보","매체 의사소통","사회와 문화","주제 탐구 독서"],"keywords":["추천 알고리즘 필터버블","추천 목록 다양성","반향실 미디어"],"next":["추천 다양성 지표 만들기","뉴스 추천과 음악 추천 비교","사용자 리터러시 가이드 제작"],"difficulty":2,"time":"5~8시간","tools":"화면 기록, 분류표, 정책문서","approval":"설문 시 교사 승인","output":"추천 다양성 분석표 + 리터러시 가이드"});
pushTopic("hum", {"id":"hum-ai-translation","title":"AI 번역의 한국어 관용·은유 표현 오류 유형","kyeol":"cmp","methods":["literature","data"],"grades":[1,2,3],"link":"언어학자·번역가는 번역 결과를 정답 하나로 평가하기보다 의미, 맥락, 자연스러움, 문화 정보를 함께 비교해요.","questions":["한국어 속담·관용 표현을 여러 번역 도구에 넣으면 어떤 오류 유형이 반복될까?","직역·의역 중 원문의 의미와 분위기를 더 잘 보존하는 조건은 무엇일까?","문맥 문장을 추가하면 번역 오류가 줄어들까?"],"research":["관용어와 은유","기계번역과 생성형 번역의 차이","번역의 등가성과 맥락","평가기준표와 평가자 일치"],"steps":["저작권 문제가 없는 짧은 예문 또는 직접 만든 관용 표현 문장 20개를 선정해요.","2~3개 번역 도구에 같은 입력을 사용해 결과를 저장해요.","직역·의미 누락·문화 오해·자연스러움 등 오류 기준을 먼저 정해 분류해요.","문맥을 한두 문장 추가해 다시 번역하고 변화가 있는지 비교해요.","사람 번역을 절대적 정답으로 두기보다 사전·용례·공식 번역을 근거로 평가해요."],"subjects":["공통국어1·2","공통영어1·2","화법과 언어","영어 발표와 토론","언어생활 탐구","심화 영어 독해와 작문"],"keywords":["AI 번역 관용어 오류","기계번역 은유","번역 문맥 비교"],"next":["전문용어 번역 비교","문학 분위기 번역","한국 지역어 번역의 한계"],"difficulty":2,"time":"5~7시간","tools":"번역 도구, 스프레드시트, 사전","approval":"불필요","output":"오류 유형표 + 개선 입력 지침"});
pushTopic("edu", {"id":"edu-gamification","title":"게이미피케이션 요소와 학습 참여의 관계","kyeol":"exp","methods":["practice","survey","literature"],"grades":[1,2,3],"link":"교사와 에듀테크 기획자는 포인트·배지·도전 과제 같은 요소가 학습을 돕는지 실제 사용성과 학습과정을 확인해요.","questions":["같은 짧은 학습 과제를 일반형과 포인트·진행 표시형으로 제시하면 완료율과 만족도는 어떻게 다를까?","랭킹처럼 경쟁적인 요소와 개인 진행률 요소는 학생에게 어떤 차이를 만들까?","게임 요소가 학습내용보다 보상에만 집중하게 만드는 경우는 언제일까?"],"research":["게이미피케이션 요소","자기결정성 이론","내재·외재 동기","사람 대상 교육 탐구의 윤리"],"steps":["교사 승인 후 성적과 무관한 5~10분짜리 동일 난이도 과제를 두 형태로 만들어요.","무작위 강제 배정 대신 참여자가 불이익 없이 선택·중단할 수 있게 안내해요.","완료 여부·걸린 시간·익명 만족도처럼 최소 정보만 기록해요.","학습 성취를 단정하기보다 참여 행동과 자기보고의 차이를 분석해요.","랭킹 공개처럼 압박을 줄 수 있는 기능은 사용하지 않아요.","학생을 존중하는 게임화 원칙을 제안해요."],"subjects":["사회와 문화","인간과 심리","독서 토론과 글쓰기","실용 통계"],"keywords":["게이미피케이션 학습동기","포인트 배지 학습","자기결정성 에듀테크"],"next":["즉시 피드백과 지연 피드백","학습 진행률 표시 UX","협력형 게임 요소 비교"],"difficulty":2,"time":"6~8시간","tools":"간단한 퀴즈/폼, 익명 설문","approval":"교사 승인 필요","output":"참여 비교표 + 교육 설계 원칙"});
pushTopic("arts", {"id":"arts-biomechanics","title":"운동화 구조와 착지 충격을 안전하게 비교하기","kyeol":"exp","methods":["experiment","data","literature"],"grades":[2,3],"link":"스포츠과학자·제품 디자이너는 인체 움직임과 소재 특성을 함께 분석하지만, 사람에게 위험을 주지 않는 측정 설계를 우선해요.","questions":["운동화 중창 재료와 구조는 충격 흡수 원리를 어떻게 다르게 설명할 수 있을까?","사람이 점프해 최대 충격을 경쟁시키지 않고 동일한 낙하 모형을 사용하면 신발별 가속도 패턴은 어떻게 다를까?","실험 결과와 제조사 주장 사이에서 확인 가능한 것과 확인할 수 없는 것은 무엇일까?"],"research":["충격량과 충돌시간","가속도 센서의 원리와 한계","EVA·폼 등 중창 소재","스포츠 제품 성능 시험의 통제변인"],"steps":["사람의 반복 점프 대신 동일한 질량의 안전한 낙하 모형을 사용하도록 설계해요.","신발 내부 또는 위에 센서를 같은 위치로 고정할 방법을 정해요.","같은 높이에서 여러 번 떨어뜨려 최대 가속도와 지속 시간을 기록해요.","조건별 평균과 변동 범위를 비교해요.","휴대폰 센서가 전문 충격 측정 장비가 아니라는 한계를 적어요.","성능 우열을 단정하지 않고 구조와 측정값의 관계를 설명해요."],"safety":["사람의 신체에 충격을 주는 실험은 하지 않아요.","낙하 물체가 튀지 않도록 낮은 높이와 안전구역에서 교사 지도 아래 실시해요."],"subjects":["체육1·2","스포츠 과학","물리학","역학과 에너지"],"keywords":["운동화 쿠션 충격량","중창 소재 EVA","가속도 센서 충격 실험"],"next":["인솔 재료 비교","달리기화 구조 문헌 비교","착지 동작 영상의 관절각 분석"],"difficulty":3,"time":"8~10시간","tools":"운동화, 동일 질량 모형, 센서","approval":"교사 승인 필요","output":"충격 비교 그래프 + 제품 설계 해석"});
