function methodSpec(label, q){
  const s=(label+' '+q).toLowerCase();
  // 야외·현장 관찰은 실험과 구분해 안전 안내를 맞춥니다.
  if(/무장애|보행 안전|해양 쓰레기|생물다양성|열섬|그늘|분리배출|현장 관찰|지도화|관찰·분류|조도/.test(s)) return {methods:['observe','data'],k:'data',difficulty:2,tools:'현장 기록표·사진 또는 측정 도구'};
  // 사람의 반응·학습·판별을 직접 비교하면 사람 대상 탐구로 분류합니다.
  if(/딥페이크.*구별|퀴즈|피드백|학습계획|알림을 끈|행동 의도|이해도|기억도|실천 의지|참여 만족도|학습 시간|수면 습관/.test(s)) return {methods:['people','survey'],k:'exp',difficulty:2,tools:'익명 참여 활동·설문, 스프레드시트'};
  if(/알고리즘 추천|추천 콘텐츠|추천 목록/.test(s)) return {methods:['observe','literature','data'],k:'data',difficulty:2,tools:'화면 기록·플랫폼 정책문서·분류표'};
  if(/지역 축제/.test(s)) return {methods:['observe','literature','data'],k:'soc',difficulty:2,tools:'공공자료·현장 관찰 기록표'};
  if(/공부 공간.*소음|온습도.*쾌적성/.test(s)) return {methods:['observe','survey','data'],k:'data',difficulty:2,tools:'측정도구·익명 설문·스프레드시트'};
  if(/제작|코딩|설계|웹앱|콘텐츠 제작|수납도구|빗물받이|자동 조명/.test(s)) return {methods:['making','practice'],k:'exp',difficulty:2,tools:'제작 도구 또는 컴퓨터'};
  if(/설문|인터뷰|인식|만족|선호/.test(s)) return {methods:['survey','data'],k:'soc',difficulty:2,tools:'익명 설문, 스프레드시트'};
  if(/강도|거치대|단열|센서|실험|온도 측정|심박|충전|발열/.test(s)) return {methods:['experiment','data'],k:'exp',difficulty:2,tools:'주제별 안전 측정 도구'};
  if(/근로계약|esg|웹툰|언론사|역사적 사건|광고|의약품/.test(s)) return {methods:['literature'],k:'cmp',difficulty:1,tools:'공식자료·책·논문'};
  if(/공공데이터|통계|그래프|kosis|계산|인구|강수량/.test(s)) return {methods:['data','literature'],k:'data',difficulty:2,tools:'공공데이터, 스프레드시트'};
  return {methods:['literature'],k:'cmp',difficulty:1,tools:'공식자료·책·논문'};
}
function stableTopicId(fid,title){
  let h=2166136261;
  const str=fid+'|'+normTitle(title);
  for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619);}
  return `att-${fid}-${(h>>>0).toString(36)}`;
}
function compactTopic(fid,title,q,methodLabel,output,idx){
  const sp=methodSpec(methodLabel+' '+title,q);
  const survey=sp.methods.includes('survey');
  const making=sp.methods.includes('making');
  const direct=/측정|관찰|실험|제작|코딩|지도|설문/.test(methodLabel+' '+q);
  const idTitle=title.replace(/[?？]$/,'').trim();
  let cleanTitle=idTitle;
  const cleanQ=q.replace(/[?？]$/,'').trim();
  // 질문이 제목으로 시작하고 뒤가 더 이어질 때만 '잘린 제목'으로 판단해 복원합니다.
  if(cleanQ.startsWith(cleanTitle) && cleanQ.length > cleanTitle.length) cleanTitle=cleanQ;
  const research=[
    `${cleanTitle}에 관련된 핵심 개념과 용어`,
    '공식기관·교과서·논문 등 신뢰할 수 있는 자료에서 기존 결과 확인하기',
    '내가 비교할 대상·기간·조건과 측정 기준 정하기',
    direct ? '반복 측정·비교에서 통제해야 할 조건과 오차' : '서로 다른 자료의 주장·근거·한계를 비교하는 방법'
  ];
  if(survey) research.push('설문 문항의 중립성·익명성·표본 편향과 상관관계 해석');
  const steps=[
    `탐구 질문을 “대상 + 비교 조건 + 확인할 결과”가 드러나도록 한 문장으로 구체화해요: ${q}`,
    '관련 공식자료 1개와 책·논문·연구자료 1개 이상을 찾아 출처·날짜·핵심 근거를 기록해요.',
    direct ? `추천 방법(${methodLabel})을 바탕으로 내가 직접 수집할 자료의 기록표를 먼저 만들어요.` : '서로 다른 자료 3개 이상을 같은 기준표로 비교해요.',
    survey ? '교사 승인을 받고 이름·학번·연락처를 받지 않는 자발적 익명 조사로 진행해요.' : '조건과 단위를 통일하고, 가능하면 같은 절차를 3회 이상 반복하거나 여러 시기·사례를 비교해요.',
    '표·그래프·지도·비교표 가운데 결과를 가장 잘 보여 주는 형식 하나를 골라 정리해요.',
    '결과가 예상과 달라도 값을 고치지 말고, 자료 수·조건·측정 방법·숨은 변인을 한계로 분석해요.',
    `${output && output!=='탐구 결과물' ? output : '비교표 또는 제안서'}를 만들고 진로에서 이 결과를 어떻게 활용할지 한 문단으로 연결해요.`
  ];
  const stop=new Set(['얼마나','어떻게','무엇인가','무엇일까','달라지는가','정확할까','표시와','판별은','영향을','관계가','있는가','어떤','따라','대한','관련','탐구']);
  const kw=Array.from(new Set((cleanTitle+' '+q).replace(/[?？,.()·/]/g,' ').split(/\s+/).map(x=>x.replace(/(은|는|가|을|를|와|과|의|에|에서|으로|로)$/,'')).filter(x=>x.length>=2&&!stop.has(x)))).slice(0,5);
  return {
    id:stableTopicId(fid,idTitle),title:cleanTitle,kyeol:sp.k,methods:sp.methods,grades:sp.difficulty===1?[1,2,3]:[2,3],
    link:`${FIELDS.find(f=>f.id===fid)?.name||'관련'} 분야에서는 실제 문제를 질문으로 바꾸고 자료를 수집·비교해 근거 있는 결론과 개선안을 만들어요.`,
    questions:[q,`${q.replace(/[?？]$/,'')} — 대상이나 기간을 더 좁히면 결과는 어떻게 달라질까?`,`${cleanTitle}의 결과를 실제 학교·지역·진로 문제 해결에 적용하려면 어떤 조건이 필요할까?`],
    research,steps,
    safety: survey ? ['담당 교사의 사전 승인을 받고 참여는 자발적으로 진행해요.','이름·학번·연락처 등 개인 식별정보를 받지 않고 원자료를 다른 사람에게 공유하지 않아요.'] : [],
    subjects:FIELD_DEFAULT_SUBJECTS[fid]||['주제 탐구 독서','실용 통계'],
    keywords:kw,
    next:[`${cleanTitle}의 조건이나 대상을 바꾸어 재검증하기`,`${cleanTitle}와 관련된 다른 지역·시기·사례 비교하기`],
    difficulty:sp.difficulty,time:sp.difficulty===1?'3~5시간':'5~8시간',tools:sp.tools,approval:(survey||sp.methods.includes('people'))?'교사 승인 필요':(sp.methods.includes('experiment')||sp.methods.includes('practice')?'교사 확인 권장':(sp.methods.includes('observe')?'현장·야외 활동 시 교사 확인 권장':'대체로 불필요')),output:output||'탐구 보고서',
    minimum:['자료 또는 측정값 1종 확보','표·그래프 1개','결론 3문장과 한계 1가지'],
    standard:['비교 조건 2~3개','자료 3개 이상 또는 반복 측정','근거 기반 해석과 한계 작성'],
    advanced:['변인을 추가하거나 기간·대상 확대','다른 자료원과 교차검증','후속 탐구 또는 개선안 제시']
  };
}
