  if(!t.approval) t.approval = (t.methods.includes('survey')||t.methods.includes('people')||t.methods.includes('experiment')) ? '교사 확인 권장/필요' : '대체로 불필요';
  if(!t.output) t.output = t.methods.includes('making') ? '제작물 + 과정 보고서' : (t.methods.includes('data') ? '표·그래프 + 해석 보고서' : '근거 비교 보고서');
  if(!t.minimum) t.minimum=['핵심 질문 1개 확정','자료·측정값 최소 1종 확보','결과 표 또는 그래프 1개','결론 3문장 + 한계 1가지'];
