Object.entries(FIELD_KEYWORD_ADD).forEach(([id,words])=>{const f=FIELDS.find(x=>x.id===id);if(f)f.keywords=uniq((f.keywords||[]).concat(words));});
FIELDS.forEach(f=>f.topics.forEach(t=>{
  const txt=(t.title+' '+t.questions.join(' ')+' '+t.steps.join(' '));
  if(t.methods.some(m=>['survey','people','practice'].includes(m))){
    t.safety=uniq((t.safety||[]).concat(['교내 학생 대상 설문·참여 활동은 담당 교사에게 사전 승인을 받아요.','참여는 자발적이며 이름·학번·연락처·건강 진단 정보 등 개인 식별정보를 받지 않아요.','원자료는 탐구 목적 외에 공유·유포하지 않고 결과는 집단 통계로만 제시해요.']));
  }
  if(t.methods.includes('experiment') && (f.id==='chem' || /유기용매|시약|산성|산·염기|강산|강염기|중화|적정|pH/.test(txt))) t.safety=uniq((t.safety||[]).concat(['합성 시약·유기용매 등은 교사 지도 아래 사용하고 지정 폐기물 용기에 분리 배출해요. 싱크대나 일반 쓰레기에 임의 폐기하지 않아요.']));
  if(/심박|운동 전후/.test(txt)) t.safety=uniq((t.safety||[]).concat(['운동 수행은 체육·보건 담당 교사의 확인을 받고, 통증·어지럼 등 이상이 있으면 즉시 중단해요. 질환 유무를 조사하거나 무리한 운동을 시키지 않아요.']));
  if(/충전|발열/.test(txt)) t.safety=uniq((t.safety||[]).concat(['정상 인증 충전기와 케이블만 사용하고, 기기를 덮거나 고온 환경에서 가열하지 않아요. 배터리를 분해하지 않아요.']));
  if(/보건실/.test(txt)) t.safety=uniq((t.safety||[]).concat(['보건실 자료는 보건교사 승인 아래 비식별 집계자료만 사용하고 개인별 기록은 열람·복사하지 않아요.']));
  if(/이산화탄소|CO2/.test(txt)) t.tools='CO₂ 측정기, 기록표 또는 스프레드시트';
}));
